// 1. Используем const для константы и let для изменяемой переменной
const studentName = "Железный";
let sum = 0;

// 2. Массив (array) и объект (object)
const numbers = [10, 20, 30, 40, 50];
const studentInfo = {
  name: studentName,
  group: "ИИ-241",
  lab: 4
};

// 3. Цикл for для вычисления суммы
for (let i = 0; i < numbers.length; i++) {
  sum += numbers[i];
}

// 4. Условие if/else
let status = "";
if (sum > 100) {
  status = "Отлично, сумма больше 100";
} else {
  status = "Сумма слишком маленькая";
}

// 5. Возвращаем объект с полем payload
return {
  json: {
    payload: {
      info: studentInfo,
      numbers: numbers,
      totalSum: sum,
      status: status
    }
  }
};
